1	package com.example.starter.baggage;
2	
3	import java.time.Instant;
4	import java.time.OffsetDateTime;
5	import java.time.ZoneOffset;
6	import java.util.ArrayList;
7	import java.util.HashSet;
8	import java.util.List;
9	import java.util.Set;
10	import java.util.function.Supplier;
11	
12	import com.fasterxml.jackson.databind.ObjectMapper;
13	import org.springframework.jdbc.core.JdbcTemplate;
14	import org.springframework.jdbc.core.RowMapper;
15	import org.springframework.stereotype.Service;
16	
17	import com.example.starter.baggage.BaggageDtos.ArriveRequest;
18	import com.example.starter.baggage.BaggageDtos.ArriveResponse;
19	import com.example.starter.baggage.BaggageDtos.BagResponse;
20	import com.example.starter.baggage.BaggageDtos.DifferenceArriveRequest;
21	import com.example.starter.baggage.BaggageDtos.DifferenceArriveResponse;
22	import com.example.starter.baggage.BaggageDtos.ItineraryItem;
23	import com.example.starter.baggage.BaggageDtos.LegDifferenceResponse;
24	import com.example.starter.baggage.BaggageDtos.LegResponse;
25	import com.example.starter.baggage.BaggageDtos.LoadRequest;
26	import com.example.starter.baggage.BaggageDtos.LoadResponse;
27	import com.example.starter.baggage.BaggageDtos.ManifestResponse;
28	import com.example.starter.baggage.BaggageDtos.RecoverRequest;
29	import com.example.starter.baggage.BaggageDtos.RecoverResponse;
30	import com.example.starter.baggage.BaggageDtos.RegisterBagRequest;
31	import com.example.starter.baggage.BaggageDtos.RegisterLegRequest;
32	import com.example.starter.baggage.BaggageDtos.SealRequest;
33	import com.example.starter.baggage.BaggageDtos.SealResponse;
34	import com.example.starter.baggage.BaggageDtos.ShortItem;
35	import com.example.starter.baggage.BaggageDtos.ShortListResponse;
36	import com.example.starter.baggage.BaggageDtos.TraceEvent;
37	
38	/**
39	 * 联程行李装载交接核心业务：航段/行李登记、批量装载、封舱、精确/差异到达、补到与查询。
40	 * 所有写操作经 {@link IdempotencyService} 去重，业务变更与去重记录原子提交；
41	 * 航段行级锁（SELECT ... FOR UPDATE）保证装载与封舱并发时以版本决定唯一先后，
42	 * load_record 以 bag_tag 为主键保证同件行李不会进入两个清单。
43	 * 差异到达仅允许 SEALED 航段提交封舱清单子集；缺失行李转 SHORT_UNLOADED 并冻结待乘索引，
44	 * 补到前无法装载任何后续航段，补到提交后才恢复参与装载。
45	 */
46	@Service
47	public class BaggageService {
48	
49	    private static final String LEG_OPEN = "OPEN";
50	    private static final String LEG_SEALED = "SEALED";
51	    private static final String LEG_ARRIVED = "ARRIVED";
52	    private static final String ARRIVAL_EXACT = "EXACT";
53	    private static final String ARRIVAL_DIFF = "DIFF";
54	    private static final String BAG_IN_TRANSIT = "IN_TRANSIT";
55	    private static final String BAG_SHORT_UNLOADED = "SHORT_UNLOADED";
56	    private static final String BAG_RECOVERED = "RECOVERED";
57	    private static final String BAG_DELIVERED = "DELIVERED";
58	
59	    private static final String EVT_REGISTERED = "REGISTERED";
60	    private static final String EVT_LOADED = "LOADED";
61	    private static final String EVT_UNLOADED = "UNLOADED";
62	    private static final String EVT_SHORT = "SHORT_UNLOADED";
63	    private static final String EVT_RECOVERED = "RECOVERED";
64	    private static final String EVT_DELIVERED = "DELIVERED";
65	
66	    private static final RowMapper<LegRow> LEG_MAPPER = (rs, rowNum) -> new LegRow(
67	            rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"),
68	            rs.getString("status"), rs.getInt("version"), rs.getString("sealed_manifest"),
69	            rs.getString("arrival_type"), rs.getString("arrival_actual"));
70	
71	    private static final RowMapper<BagRow> BAG_MAPPER = (rs, rowNum) -> new BagRow(
72	            rs.getString("bag_tag"), rs.getString("current_location"),
73	            rs.getInt("next_leg_index"), rs.getString("status"), rs.getString("loaded_leg_id"),
74	            rs.getString("short_leg_id"), rs.getString("short_destination"),
75	            getInstant(rs, "short_registered_at"));
76	
77	    private static final RowMapper<ItineraryItem> ITINERARY_MAPPER = (rs, rowNum) -> new ItineraryItem(
78	            rs.getInt("seq"), rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"));
79	
80	    private static final RowMapper<TraceEvent> EVENT_MAPPER = (rs, rowNum) -> new TraceEvent(
81	            rs.getInt("seq"), rs.getString("event_type"), rs.getString("leg_id"),
82	            rs.getString("location"), getInstant(rs, "event_time").toString());
83	
84	    private static final RowMapper<ShortItem> SHORT_MAPPER = (rs, rowNum) -> new ShortItem(
85	            rs.getString("bag_tag"), rs.getString("short_leg_id"), rs.getString("short_destination"),
86	            getInstant(rs, "short_registered_at").toString(),
87	            rs.getInt("next_leg_index"), rs.getString("current_location"));
88	
89	    private final JdbcTemplate jdbcTemplate;
90	    private final IdempotencyService idempotencyService;
91	    private final ObjectMapper objectMapper;
92	    /** 可控时钟，默认系统 UTC 时钟，测试可替换。 */
93	    private Supplier<Instant> clock = Instant::now;
94	
95	    public BaggageService(JdbcTemplate jdbcTemplate,
96	                          IdempotencyService idempotencyService,
97	                          ObjectMapper objectMapper) {
98	        this.jdbcTemplate = jdbcTemplate;
99	        this.idempotencyService = idempotencyService;
100	        this.objectMapper = objectMapper;
101	    }
102	
103	    /** 替换时钟（测试使用），所有登记时刻均取该时钟的 UTC 时刻。 */
104	    void setClock(Supplier<Instant> clock) {
105	        this.clock = clock;
106	    }
107	
108	    /** 登记航段：legId 唯一，初始状态 OPEN、版本 1。 */
109	    public LegResponse registerLeg(RegisterLegRequest request) {
110	        return idempotencyService.execute(request.requestId(), "REGISTER_LEG", 201,
111	                request, LegResponse.class, () -> doRegisterLeg(request));
112	    }
113	
114	    /** 登记行李：1~5 个无重复有序航段，相邻航段首尾站衔接，初始位于首段始发站。 */
115	    public BagResponse registerBag(RegisterBagRequest request) {
116	        return idempotencyService.execute(request.requestId(), "REGISTER_BAG", 201,
117	                request, BagResponse.class, () -> doRegisterBag(request));
118	    }
119	
120	    /** 批量装载：整批原子，任一行李不满足则 422 且无一件移动。 */
121	    public LoadResponse load(String legId, LoadRequest request) {
122	        LoadPayload payload = new LoadPayload(legId, request.expectedVersion(), sortedCopy(request.bagTags()));
123	        return idempotencyService.execute(request.requestId(), "LOAD", 200,
124	                payload, LoadResponse.class, () -> doLoad(legId, request));
125	    }
126	
127	    /** 封舱：校验版本，保存只读装载清单并转 SEALED；空清单也可封舱。 */
128	    public SealResponse seal(String legId, SealRequest request) {
129	        SealPayload payload = new SealPayload(legId, request.expectedVersion());
130	        return idempotencyService.execute(request.requestId(), "SEAL", 200,
131	                payload, SealResponse.class, () -> doSeal(legId, request));
132	    }
133	
134	    /** 到达确认：实际袋号集合须与封舱清单完全一致，匹配则原子转 ARRIVED 并推进各行李。 */
135	    public ArriveResponse arrive(String legId, ArriveRequest request) {
136	        ArrivePayload payload = new ArrivePayload(legId, sortedCopy(request.bagTags()));
137	        return idempotencyService.execute(request.requestId(), "ARRIVE", 200,
138	                payload, ArriveResponse.class, () -> doArrive(legId, request));
139	    }
140	
141	    /**
142	     * 差异到达：仅 SEALED 航段可提交，actual 为封舱清单子集（允许空集）且不得重复。
143	     * 实际到达行李推进到到达站并推进待乘索引；缺失行李转 SHORT_UNLOADED、冻结索引；
144	     * 航段保存只读差异快照后转 ARRIVED，不能再执行另一种到达确认。
145	     */
146	    public DifferenceArriveResponse arriveDifference(String legId, DifferenceArriveRequest request) {
147	        DifferenceArrivePayload payload = new DifferenceArrivePayload(
148	                legId, request.expectedVersion(), sortedCopy(request.bagTags()));
149	        return idempotencyService.execute(request.requestId(), "ARRIVE_DIFFERENCE", 200,
150	                payload, DifferenceArriveResponse.class, () -> doArriveDifference(legId, request));
151	    }
152	
153	    /**
154	     * 补到：仅 SHORT_UNLOADED 且缺失航段匹配的行李可补到，实际站必须等于该航段到达站（否则 422）。
155	     * 成功后移动行李、推进待乘索引并标记 RECOVERED（完成行程者 DELIVERED）；
156	     * 相同补到同参由 requestId 重放原结果，已补到不得再次推进。
157	     */
158	    public RecoverResponse recover(RecoverRequest request) {
159	        return idempotencyService.execute(request.requestId(), "RECOVER", 200,
160	                request, RecoverResponse.class, () -> doRecover(request));
161	    }
162	
163	    /** 行李完整轨迹查询。 */
164	    public BagResponse getBagTrace(String bagTag) {
165	        BagRow bag = findBag(bagTag);
166	        if (bag == null) {
167	            throw ApiException.notFound("行李不存在: " + bagTag);
168	        }
169	        return toBagResponse(bag);
170	    }
171	
172	    /** 封舱清单查询：未封舱时返回空清单。 */
173	    public ManifestResponse getManifest(String legId) {
174	        LegRow leg = findLeg(legId);
175	        if (leg == null) {
176	            throw ApiException.notFound("航段不存在: " + legId);
177	        }
178	        List<String> manifest = leg.sealedManifest() == null ? List.of() : readJsonList(leg.sealedManifest());
179	        return new ManifestResponse(leg.legId(), leg.status(), leg.version(), manifest);
180	    }
181	
182	    /** 航段差异快照查询：返回只读封舱清单、到达类型及差异到达实际集合。 */
183	    public LegDifferenceResponse getDifference(String legId) {
184	        LegRow leg = findLeg(legId);
185	        if (leg == null) {
186	            throw ApiException.notFound("航段不存在: " + legId);
187	        }
188	        List<String> manifest = leg.sealedManifest() == null ? List.of() : readJsonList(leg.sealedManifest());
189	        List<String> actual = switch (leg.arrivalType() == null ? "" : leg.arrivalType()) {
190	            case ARRIVAL_DIFF -> leg.arrivalActual() == null ? List.of() : readJsonList(leg.arrivalActual());
191	            case ARRIVAL_EXACT -> manifest;
192	            default -> null;
193	        };
194	        return new LegDifferenceResponse(leg.legId(), leg.status(), leg.version(),
195	                manifest, leg.arrivalType(), actual);
196	    }
197	
198	    /** 未补到短卸行李清单查询：仅含当前仍为 SHORT_UNLOADED 的行李。 */
199	    public ShortListResponse listShortUnloaded() {
200	        List<ShortItem> items = jdbcTemplate.query(
201	                "SELECT bag_tag, short_leg_id, short_destination, short_registered_at,"
202	                        + " next_leg_index, current_location FROM bag"
203	                        + " WHERE status = ? ORDER BY short_registered_at, bag_tag",
204	                SHORT_MAPPER, BAG_SHORT_UNLOADED);
205	        return new ShortListResponse(items);
206	    }
207	
208	    private LegResponse doRegisterLeg(RegisterLegRequest request) {
209	        if (findLeg(request.legId()) != null) {
210	            throw ApiException.conflict("航段已存在: " + request.legId());
211	        }
212	        jdbcTemplate.update(
213	                "INSERT INTO leg (leg_id, origin, destination, status, version) VALUES (?, ?, ?, ?, 1)",
214	                request.legId(), request.origin(), request.destination(), LEG_OPEN);
215	        return new LegResponse(request.legId(), request.origin(), request.destination(), LEG_OPEN, 1);
216	    }
217	
218	    private BagResponse doRegisterBag(RegisterBagRequest request) {
219	        List<String> legIds = request.legIds();
220	        if (new HashSet<>(legIds).size() != legIds.size()) {
221	            throw ApiException.unprocessable("行程航段不得重复");
222	        }
223	        if (findBag(request.bagTag()) != null) {
224	            throw ApiException.conflict("行李已存在: " + request.bagTag());
225	        }
226	        List<LegRow> legs = new ArrayList<>();
227	        for (String legId : legIds) {
228	            LegRow leg = findLeg(legId);
229	            if (leg == null) {
230	                throw ApiException.unprocessable("行程引用的航段不存在: " + legId);
231	            }
232	            legs.add(leg);
233	        }
234	        for (int i = 0; i + 1 < legs.size(); i++) {
235	            if (!legs.get(i).destination().equals(legs.get(i + 1).origin())) {
236	                throw ApiException.unprocessable(
237	                        "相邻航段首尾站必须衔接: " + legs.get(i).legId() + " -> " + legs.get(i + 1).legId());
238	            }
239	        }
240	        String startStation = legs.get(0).origin();
241	        jdbcTemplate.update(
242	                "INSERT INTO bag (bag_tag, current_location, next_leg_index, status) VALUES (?, ?, 0, ?)",
243	                request.bagTag(), startStation, BAG_IN_TRANSIT);
244	        for (int i = 0; i < legs.size(); i++) {
245	            LegRow leg = legs.get(i);
246	            jdbcTemplate.update(
247	                    "INSERT INTO bag_itinerary (bag_tag, seq, leg_id, origin, destination) VALUES (?, ?, ?, ?, ?)",
248	                    request.bagTag(), i, leg.legId(), leg.origin(), leg.destination());
249	        }
250	        insertEvent(request.bagTag(), EVT_REGISTERED, null, startStation);
251	        return toBagResponse(findBag(request.bagTag()));
252	    }
253	
254	    private LoadResponse doLoad(String legId, LoadRequest request) {
255	        LegRow leg = lockLeg(legId);
256	        checkVersion(leg, request.expectedVersion());
257	        if (!LEG_OPEN.equals(leg.status())) {
258	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止装载");
259	        }
260	        List<String> bagTags = request.bagTags();
261	        if (new HashSet<>(bagTags).size() != bagTags.size()) {
262	            throw ApiException.unprocessable("批量装载的 bagTag 不得重复");
263	        }
264	        List<String> sorted = sortedCopy(bagTags);
265	        List<BagRow> bags = new ArrayList<>();
266	        for (String bagTag : sorted) {
267	            BagRow bag = lockBag(bagTag);
268	            if (bag == null) {
269	                throw ApiException.unprocessable("行李不存在: " + bagTag);
270	            }
271	            validateLoadable(bag, leg);
272	            bags.add(bag);
273	        }
274	        for (BagRow bag : bags) {
275	            jdbcTemplate.update("INSERT INTO load_record (bag_tag, leg_id) VALUES (?, ?)", bag.bagTag(), legId);
276	            jdbcTemplate.update("UPDATE bag SET loaded_leg_id = ? WHERE bag_tag = ?", legId, bag.bagTag());
277	            insertEvent(bag.bagTag(), EVT_LOADED, legId, leg.origin());
278	        }
279	        int newVersion = leg.version() + 1;
280	        jdbcTemplate.update("UPDATE leg SET version = ? WHERE leg_id = ?", newVersion, legId);
281	        return new LoadResponse(legId, LEG_OPEN, newVersion, sorted);
282	    }
283	
284	    private SealResponse doSeal(String legId, SealRequest request) {
285	        LegRow leg = lockLeg(legId);
286	        checkVersion(leg, request.expectedVersion());
287	        if (!LEG_OPEN.equals(leg.status())) {
288	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止封舱");
289	        }
290	        List<String> manifest = jdbcTemplate.queryForList(
291	                "SELECT bag_tag FROM load_record WHERE leg_id = ? ORDER BY bag_tag", String.class, legId);
292	        int newVersion = leg.version() + 1;
293	        jdbcTemplate.update("UPDATE leg SET status = ?, version = ?, sealed_manifest = ? WHERE leg_id = ?",
294	                LEG_SEALED, newVersion, writeJson(manifest), legId);
295	        return new SealResponse(legId, LEG_SEALED, newVersion, manifest);
296	    }
297	
298	    private ArriveResponse doArrive(String legId, ArriveRequest request) {
299	        LegRow leg = lockLeg(legId);
300	        if (!LEG_SEALED.equals(leg.status())) {
301	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止到达确认");
302	        }
303	        List<String> manifest = readJsonList(leg.sealedManifest());
304	        List<String> actual = request.bagTags();
305	        Set<String> actualSet = new HashSet<>(actual);
306	        if (actualSet.size() != actual.size() || !actualSet.equals(new HashSet<>(manifest))) {
307	            throw ApiException.unprocessable("实际袋号集合与封舱清单不一致");
308	        }
309	        for (String bagTag : manifest) {
310	            BagRow bag = lockBag(bagTag);
311	            advanceArrivedBag(bag, leg.destination(), legId);
312	        }
313	        jdbcTemplate.update("DELETE FROM load_record WHERE leg_id = ?", legId);
314	        int newVersion = leg.version() + 1;
315	        jdbcTemplate.update(
316	                "UPDATE leg SET status = ?, version = ?, arrival_type = ?, arrival_actual = NULL WHERE leg_id = ?",
317	                LEG_ARRIVED, newVersion, ARRIVAL_EXACT, legId);
318	        return new ArriveResponse(legId, LEG_ARRIVED, newVersion, sortedCopy(manifest));
319	    }
320	
321	    private DifferenceArriveResponse doArriveDifference(String legId, DifferenceArriveRequest request) {
322	        LegRow leg = lockLeg(legId);
323	        checkVersion(leg, request.expectedVersion());
324	        if (!LEG_SEALED.equals(leg.status())) {
325	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止差异到达");
326	        }
327	        List<String> manifest = readJsonList(leg.sealedManifest());
328	        List<String> actual = request.bagTags();
329	        Set<String> actualSet = new HashSet<>(actual);
330	        if (actualSet.size() != actual.size()) {
331	            throw ApiException.unprocessable("实际袋号集合不得重复");
332	        }
333	        if (!new HashSet<>(manifest).containsAll(actualSet)) {
334	            throw ApiException.unprocessable("实际袋号存在封舱清单外袋号，整次差异到达拒绝");
335	        }
336	        List<String> arrivedSorted = sortedCopy(actual);
337	        List<String> shortList = manifest.stream()
338	                .filter(bagTag -> !actualSet.contains(bagTag))
339	                .sorted()
340	                .toList();
341	        OffsetDateTime registeredAt = OffsetDateTime.ofInstant(clock.get(), ZoneOffset.UTC);
342	        for (String bagTag : manifest) {
343	            BagRow bag = lockBag(bagTag);
344	            if (actualSet.contains(bagTag)) {
345	                advanceArrivedBag(bag, leg.destination(), legId);
346	            } else {
347	                jdbcTemplate.update(
348	                        "UPDATE bag SET status = ?, loaded_leg_id = NULL, short_leg_id = ?,"
349	                                + " short_destination = ?, short_registered_at = ? WHERE bag_tag = ?",
350	                        BAG_SHORT_UNLOADED, legId, leg.destination(), registeredAt, bagTag);
351	                insertEvent(bagTag, EVT_SHORT, legId, bag.currentLocation());
352	            }
353	        }
354	        jdbcTemplate.update("DELETE FROM load_record WHERE leg_id = ?", legId);
355	        int newVersion = leg.version() + 1;
356	        jdbcTemplate.update(
357	                "UPDATE leg SET status = ?, version = ?, arrival_type = ?, arrival_actual = ? WHERE leg_id = ?",
358	                LEG_ARRIVED, newVersion, ARRIVAL_DIFF, writeJson(arrivedSorted), legId);
359	        return new DifferenceArriveResponse(legId, LEG_ARRIVED, newVersion, arrivedSorted, shortList);
360	    }
361	
362	    private RecoverResponse doRecover(RecoverRequest request) {
363	        BagRow bag = lockBag(request.bagTag());
364	        if (bag == null) {
365	            throw ApiException.notFound("行李不存在: " + request.bagTag());
366	        }
367	        if (!BAG_SHORT_UNLOADED.equals(bag.status())) {
368	            if (BAG_RECOVERED.equals(bag.status()) || BAG_DELIVERED.equals(bag.status())) {
369	                throw ApiException.conflict("行李 " + bag.bagTag() + " 已补到，不得再次推进");
370	            }
371	            throw ApiException.unprocessable(
372	                    "行李 " + bag.bagTag() + " 状态为 " + bag.status() + "，不可补到");
373	        }
374	        if (!bag.shortLegId().equals(request.missingLegId())) {
375	            throw ApiException.conflict(
376	                    "缺失航段不匹配: 登记为 " + bag.shortLegId() + "，提交为 " + request.missingLegId());
377	        }
378	        LegRow missingLeg = findLeg(request.missingLegId());
379	        if (missingLeg == null) {
380	            throw ApiException.unprocessable("缺失航段不存在: " + request.missingLegId());
381	        }
382	        if (!missingLeg.destination().equals(request.actualStation())) {
383	            throw ApiException.unprocessable(
384	                    "实际到站 " + request.actualStation() + " 与缺失航段应到站 "
385	                            + missingLeg.destination() + " 不一致");
386	        }
387	        int nextIndex = bag.nextLegIndex() + 1;
388	        int total = itineraryCount(bag.bagTag());
389	        String newStatus = nextIndex >= total ? BAG_DELIVERED : BAG_RECOVERED;
390	        jdbcTemplate.update(
391	                "UPDATE bag SET current_location = ?, next_leg_index = ?, status = ?, loaded_leg_id = NULL,"
392	                        + " short_leg_id = NULL, short_destination = NULL, short_registered_at = NULL"
393	                        + " WHERE bag_tag = ?",
394	                request.actualStation(), nextIndex, newStatus, bag.bagTag());
395	        insertEvent(bag.bagTag(), EVT_RECOVERED, request.missingLegId(), request.actualStation());
396	        if (BAG_DELIVERED.equals(newStatus)) {
397	            insertEvent(bag.bagTag(), EVT_DELIVERED, request.missingLegId(), request.actualStation());
398	        }
399	        return new RecoverResponse(bag.bagTag(), newStatus, request.actualStation(),
400	                nextIndex, request.missingLegId());
401	    }
402	
403	    /** 实际到达行李的统一推进：移动到到达站、推进待乘索引，完成行程者交付。 */
404	    private void advanceArrivedBag(BagRow bag, String destination, String legId) {
405	        int nextIndex = bag.nextLegIndex() + 1;
406	        int total = itineraryCount(bag.bagTag());
407	        String status = nextIndex >= total ? BAG_DELIVERED : BAG_IN_TRANSIT;
408	        jdbcTemplate.update(
409	                "UPDATE bag SET current_location = ?, next_leg_index = ?, status = ?, loaded_leg_id = NULL"
410	                        + " WHERE bag_tag = ?",
411	                destination, nextIndex, status, bag.bagTag());
412	        insertEvent(bag.bagTag(), EVT_UNLOADED, legId, destination);
413	        if (BAG_DELIVERED.equals(status)) {
414	            insertEvent(bag.bagTag(), EVT_DELIVERED, legId, destination);
415	        }
416	    }
417	
418	    private void validateLoadable(BagRow bag, LegRow leg) {
419	        if (BAG_SHORT_UNLOADED.equals(bag.status())) {
420	            throw ApiException.unprocessable(
421	                    "行李 " + bag.bagTag() + " 处于短卸状态，须先补到才能装载后续航段");
422	        }
423	        if (bag.loadedLegId() != null) {
424	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已装载到航段 " + bag.loadedLegId());
425	        }
426	        ItineraryItem next = nextItinerary(bag.bagTag(), bag.nextLegIndex());
427	        if (next == null) {
428	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已完成全部行程");
429	        }
430	        if (!next.legId().equals(leg.legId())) {
431	            throw ApiException.unprocessable(
432	                    "行李 " + bag.bagTag() + " 当前待乘航段为 " + next.legId() + "，不能装载到 " + leg.legId());
433	        }
434	        if (!bag.currentLocation().equals(leg.origin())) {
435	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 不在航段始发站 " + leg.origin());
436	        }
437	    }
438	
439	    private void checkVersion(LegRow leg, int expectedVersion) {
440	        if (leg.version() != expectedVersion) {
441	            throw ApiException.conflict(
442	                    "航段版本冲突: 期望 " + expectedVersion + "，当前 " + leg.version());
443	        }
444	    }
445	
446	    private LegRow findLeg(String legId) {
447	        List<LegRow> rows = jdbcTemplate.query(legSelect(false), LEG_MAPPER, legId);
448	        return rows.isEmpty() ? null : rows.get(0);
449	    }
450	
451	    private LegRow lockLeg(String legId) {
452	        List<LegRow> rows = jdbcTemplate.query(legSelect(true), LEG_MAPPER, legId);
453	        if (rows.isEmpty()) {
454	            throw ApiException.notFound("航段不存在: " + legId);
455	        }
456	        return rows.get(0);
457	    }
458	
459	    private static String legSelect(boolean forUpdate) {
460	        return "SELECT leg_id, origin, destination, status, version, sealed_manifest,"
461	                + " arrival_type, arrival_actual FROM leg WHERE leg_id = ?"
462	                + (forUpdate ? " FOR UPDATE" : "");
463	    }
464	
465	    private BagRow findBag(String bagTag) {
466	        List<BagRow> rows = jdbcTemplate.query(bagSelect(false), BAG_MAPPER, bagTag);
467	        return rows.isEmpty() ? null : rows.get(0);
468	    }
469	
470	    private BagRow lockBag(String bagTag) {
471	        List<BagRow> rows = jdbcTemplate.query(bagSelect(true), BAG_MAPPER, bagTag);
472	        return rows.isEmpty() ? null : rows.get(0);
473	    }
474	
475	    private static String bagSelect(boolean forUpdate) {
476	        return "SELECT bag_tag, current_location, next_leg_index, status, loaded_leg_id,"
477	                + " short_leg_id, short_destination, short_registered_at FROM bag WHERE bag_tag = ?"
478	                + (forUpdate ? " FOR UPDATE" : "");
479	    }
480	
481	    private ItineraryItem nextItinerary(String bagTag, int nextLegIndex) {
482	        List<ItineraryItem> rows = jdbcTemplate.query(
483	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? AND seq = ?",
484	                ITINERARY_MAPPER, bagTag, nextLegIndex);
485	        return rows.isEmpty() ? null : rows.get(0);
486	    }
487	
488	    private int itineraryCount(String bagTag) {
489	        Integer count = jdbcTemplate.queryForObject(
490	                "SELECT COUNT(*) FROM bag_itinerary WHERE bag_tag = ?", Integer.class, bagTag);
491	        return count == null ? 0 : count;
492	    }
493	
494	    private List<ItineraryItem> toItinerary(String bagTag) {
495	        return jdbcTemplate.query(
496	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? ORDER BY seq",
497	                ITINERARY_MAPPER, bagTag);
498	    }
499	
500	    private List<TraceEvent> toEvents(String bagTag) {
501	        return jdbcTemplate.query(
502	                "SELECT seq, event_type, leg_id, location, event_time FROM bag_event"
503	                        + " WHERE bag_tag = ? ORDER BY seq",
504	                EVENT_MAPPER, bagTag);
505	    }
506	
507	    /** 在持有行李行锁后追加事件，seq 按该行李已有事件数递增。 */
508	    private void insertEvent(String bagTag, String eventType, String legId, String location) {
509	        Integer maxSeq = jdbcTemplate.queryForObject(
510	                "SELECT MAX(seq) FROM bag_event WHERE bag_tag = ?", Integer.class, bagTag);
511	        int nextSeq = maxSeq == null ? 0 : maxSeq + 1;
512	        jdbcTemplate.update(
513	                "INSERT INTO bag_event (bag_tag, seq, event_type, leg_id, location, event_time)"
514	                        + " VALUES (?, ?, ?, ?, ?, ?)",
515	                bagTag, nextSeq, eventType, legId, location,
516	                OffsetDateTime.ofInstant(clock.get(), ZoneOffset.UTC));
517	    }
518	
519	    private BagResponse toBagResponse(BagRow bag) {
520	        return new BagResponse(bag.bagTag(), bag.currentLocation(), bag.nextLegIndex(),
521	                bag.status(), bag.loadedLegId(), toItinerary(bag.bagTag()),
522	                bag.shortLegId(), bag.shortDestination(),
523	                bag.shortRegisteredAt() == null ? null : bag.shortRegisteredAt().toString(),
524	                toEvents(bag.bagTag()));
525	    }
526	
527	    private static Instant getInstant(java.sql.ResultSet rs, String column) throws java.sql.SQLException {
528	        OffsetDateTime value = rs.getObject(column, OffsetDateTime.class);
529	        return value == null ? null : value.toInstant();
530	    }
531	
532	    private static List<String> sortedCopy(List<String> values) {
533	        return values.stream().sorted().toList();
534	    }
535	
536	    private String writeJson(List<String> values) {
537	        try {
538	            return objectMapper.writeValueAsString(values);
539	        } catch (Exception ex) {
540	            throw new IllegalStateException("清单序列化失败", ex);
541	        }
542	    }
543	
544	    private List<String> readJsonList(String json) {
545	        try {
546	            return objectMapper.readValue(json,
547	                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class));
548	        } catch (Exception ex) {
549	            throw new IllegalStateException("清单反序列化失败", ex);
550	        }
551	    }
552	
553	    private record LegRow(String legId, String origin, String destination,
554	                          String status, int version, String sealedManifest,
555	                          String arrivalType, String arrivalActual) {
556	    }
557	
558	    private record BagRow(String bagTag, String currentLocation, int nextLegIndex,
559	                          String status, String loadedLegId, String shortLegId,
560	                          String shortDestination, Instant shortRegisteredAt) {
561	    }
562	
563	    /** 装载幂等摘要参数：bagTags 已排序，顺序差异不视为异参。 */
564	    private record LoadPayload(String legId, int expectedVersion, List<String> bagTags) {
565	    }
566	
567	    /** 封舱幂等摘要参数。 */
568	    private record SealPayload(String legId, int expectedVersion) {
569	    }
570	
571	    /** 到达确认幂等摘要参数：bagTags 已排序，顺序差异不视为异参。 */
572	    private record ArrivePayload(String legId, List<String> bagTags) {
573	    }
574	
575	    /** 差异到达幂等摘要参数：bagTags 已排序，顺序差异不视为异参。 */
576	    private record DifferenceArrivePayload(String legId, int expectedVersion, List<String> bagTags) {
577	    }
578	}
