348	        registerLeg("LEG1", "PEK", "SHA");
349	        registerBag("BAG1", List.of("LEG1"));
350	        load("LEG1", 1, List.of("BAG1"));
351	        seal("LEG1", 2);
352	        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());
353	
354	        // 同参重放原结果
355	        String requestId = UUID.randomUUID().toString();
356	        postJson("/api/bags/recover", Map.of("requestId", requestId,
357	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "SHA"))
358	                .andExpect(status().isOk())
359	                .andExpect(jsonPath("$.status").value("DELIVERED"));
360	        postJson("/api/bags/recover", Map.of("requestId", requestId,
361	                "bagTag", "BAG1", "missingLegId", "LEG1", "actualStation", "SHA"))
362	                .andExpect(status().isOk())
363	                .andExpect(jsonPath("$.status").value("DELIVERED"));
364	        // 事件只追加一次
365	        Integer eventCount = jdbcTemplate.queryForObject(
366	                "SELECT COUNT(*) FROM bag_event WHERE bag_tag = 'BAG1' AND event_type = 'RECOVERED'",
367	                Integer.class);
368	        assertThat(eventCount).isEqualTo(1);
369	        Integer logs = jdbcTemplate.queryForObject(
